/**
 * What THIS posting reaches, for the authorization question that names no
 * country of its own ("…in the country where the job is located?").
 *
 * Without it `conservativeDefaultAnswer` can only take the negative, which is
 * safe but throws away the postings the candidate may legally take — a
 * worldwide-remote role, or one in his own country. With it the answer is a
 * fact about the posting rather than a guess about the world.
 */
async function jobReachForAnswers(
  ctx: AgentContext,
): Promise<JobReach | undefined> {
  if (!ctx.jobId) return undefined;
  const [job] = await ctx.db
    .select({ location: jobs.location, remoteScope: jobs.remoteScope })
    .from(jobs)
    .where(eq(jobs.id, ctx.jobId))
    .limit(1);
  if (!job) return undefined;
  const { loadTenantProfile } = await import("../tenant-identity.js");
  const profile = (await loadTenantProfile()) as {
    location?: string;
    eligibility?: { workCountries?: string[] };
  } | null;
  // An empty `workCountries` means "never asked", not "may work nowhere" —
  // `sanitizeEligibility` treats absence as the permissive default, and five
  // of nine tenants carry it empty. Reading it as a prohibition answered "no"
  // to three Brazilian postings for a Brazilian candidate (measured against 40
  // real rows, 2026-08-19). Where a candidate lives is where they may work
  // unless something says otherwise, so their own country stands in.
  const declared = profile?.eligibility?.workCountries ?? [];
  return {
    location: job.location,
    remoteScope: job.remoteScope,
    workCountries: declared.length
      ? declared
      : namedPlaces(profile?.location).countries,
  };
}

