/**
 * The authorization question that names no country — the one the model was
 * answering, and getting backwards.
 *
 * Airbnb via Greenhouse asks "Are you legally authorized to work in the country
 * where the job is located?". It matches neither the US pattern nor a residence
 * question, so until 2026-08-19 there was no default and the model wrote one:
 * "Yes", three times, into a bank whose approved row said "No — I hold a B1/B2
 * visitor visa and have no US work authorization". Nothing was submitted with
 * it only because a verification gate happened to stop those runs first.
 *
 * The country is not unknowable here — it is the posting's. So the answer is
 * resolved from the posting's reach against the candidate's own work
 * countries, and never from a model.
 */
describe("conservativeDefaultAnswer: authorization where the job is located", () => {
  const BRAZIL = { workCountries: ["Brazil"] };
  const ASKED = [
    "Are you legally authorized to work in the country where the job is located?",
    "Are you legally authorized to work in the country where this position is located? *",
    "Are you authorized to work in the country of the employer?",
  ];

  it.each(ASKED)("answers no for a US posting: %s", (q) => {
    const d = conservativeDefaultAnswer(q, {
      location: "San Francisco, CA, United States",
      ...BRAZIL,
    });
    expect(d).not.toBeNull();
    expect(d!.answer).toMatch(/^No/);
    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
  });

  it("answers no for a posting based where the candidate cannot work", () => {
    // Berlin: as false to claim as the US, and the model would have said yes.
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "Berlin/Remote",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^No/);
  });

  it("answers yes when the posting reaches a country the candidate may work in", () => {
    // The negative is conservative, not automatic: on a worldwide-remote role
    // the candidate IS authorized where the work happens, and answering "no"
    // would throw away a job he can legally take.
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "Anywhere in the World",
      remoteScope: "worldwide",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^Yes/);
    expect(resolveBooleanAnswer(d!.answer)).toBe("yes");
  });

  it("answers yes for a posting in the candidate's own country", () => {
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "São Paulo, Brazil",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^Yes/);
  });

  /**
   * The two cases 40 real postings caught that invented locations did not.
   *
   * The first pass used `reachAllows`, which answers "can this candidate take
   * this job" — a worldwide posting is yes there whatever its location line
   * says. Run against production rows on 2026-08-19 it claimed US
   * authorization on Atlassian (San Francisco) and Overvak (New York), which
   * is the exact fabrication the branch exists to stop, and denied it on three
   * Brazilian postings for a Brazilian candidate.
   */
  it("does not claim the US on a US posting the row calls worldwide", () => {
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "San Francisco, California, USA",
      remoteScope: "worldwide",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^No/);
  });

  it("still says yes when a worldwide posting names no country at all", () => {
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "Remote",
      remoteScope: "worldwide",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^Yes/);
  });

  it("answers the residence question with its own true answer", () => {
    // "…in the country where you reside" is a different question, and its true
    // answer for someone working legally where they live is yes. A blanket
    // negative here would be as false as the positive is for the US — and
    // until 2026-08-21 it got no answer at all, which under the no-wall policy
    // is not neutrality, it is an application that never goes out.
    expect(
      conservativeDefaultAnswer(
        "Are you legally authorized to work in the country in which you reside?",
        { location: "Remote - USA", ...BRAZIL },
      )?.answer,
    ).toMatch(/^Yes/);
  });

  it("still answers the US question with the US default", () => {
    const d = conservativeDefaultAnswer(
      "Are you legally authorized to work in the United States?",
      {
        location: "Anywhere in the World",
        remoteScope: "worldwide",
        ...BRAZIL,
      },
    );
    // Even on a worldwide posting: the question names the US, and the answer
    // about the US does not change with where the role is advertised.
    expect(d!.answer).toMatch(/not authorized to work in the United States/);
  });
});

